"""
Test Flask application to verify dummy_package loads in web frameworks.
"""

try:
    print("Running test_flask.py")
    print("Importing Flask and dummy_package...")

    from flask import Flask
    import dummy_package

    app = Flask(__name__)

    @app.route('/')
    def home():
        return f"Flask app running with dummy_package v{dummy_package.get_info()['version']}"

    @app.route('/status')
    def status():
        return {
            'app': 'test_flask',
            'dummy_package_imported': dummy_package.get_import_status(),
            'version': dummy_package.get_info()['version']
        }

    print("Flask app created successfully!")
    print("To test, run: curl http://localhost:5000 or visit in browser")

except ImportError as e:
    print(f"Import error: {e}")
except Exception as e:
    print(f"Error: {e}")

# Keep the script from exiting if not running the server
if __name__ == '__main__':
    app.run(port=5000, debug=False)
